. "$PSScriptRoot/PhaseA.Tests.ps1"
. "$PSScriptRoot/PhaseA.Stage3.ps1"
$root=Join-Path ([IO.Path]::GetTempPath()) ('ether-phase-a-store-'+('a'*32));$f=@{root=$root};$records=New-Object 'System.Collections.Generic.List[object]';$observations=New-Object 'System.Collections.Generic.List[object]';$m=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;$broker=$journal[0].accountSid;$legacy=$journal[1].accountSid;$state=@{acl=$null};$io=@{Exists={param($p) $true};Apply={param($p,$acl) $state.acl=$acl}.GetNewClosure();Read={param($p) $state.acl}.GetNewClosure()}
foreach($i in 0,1,2){$role=@('root','protected','control')[$i];$path=if($i -eq 0){$root}else{Join-Path $root $role};$full=if($i -eq 0){@($m,'S-1-5-18')}elseif($i -eq 1){@($m,'S-1-5-18',$broker)}else{@($m,'S-1-5-18',$broker,$legacy)};$read=if($i -eq 0){@($broker,$legacy)}else{@()};$null=Invoke-PhaseARecordedFixtureAcl $records $f $role $path $i $full $read 'INJECTED' $io;$r=$records[$i];$observations.Add(@{status='OBSERVED';reason='NONE';fixtureId=$r.fixtureId;role=$role;relative=$r.relative;sequence=$i;descriptor=$r.actual;protected=$true;source='INJECTED'})}
$ev=@{cleanupVerified=$true;aclEstablishment=$records;aclCorroboration=$observations;aclFixtureBinding=@{fixtureId=[IO.Path]::GetFileName($root);rootIdentity=$root;brokerSid=$broker;legacySid=$legacy;source='INJECTED'}}
$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $ev 'SIMULATED_PASS' $journal.ToArray();if($v.cases.aclInspection.state -cne 'PASS'){throw 'ACL_INSPECTION_PASS_MISSING'}
$verify=New-PhaseAEvidenceVerifier $journal.ToArray() $v '1' $true $true 'SIMULATED_PASS' @() @{} $ev;if(-not (& $verify 'aclInspection' $v.cases.aclInspection $v)){throw 'ACL_INSPECTION_PROOF_FAILED'}
$fake=$v.cases.aclInspection.Clone();$fake.proof='0'*64;if(& $verify 'aclInspection' $fake $v){throw 'FORGED_PROOF_ACCEPTED'}
foreach($case in @('wrongTarget','wrongFixture','missingObservation','readFailed','contradictory','stale','missingRecord','relabeled')){
 $e=$ev.Clone();$e.aclEstablishment=@($records.ToArray()|ForEach-Object {$_.Clone()});$e.aclCorroboration=@($observations.ToArray()|ForEach-Object {$_.Clone()});$e.aclFixtureBinding=$ev.aclFixtureBinding.Clone();$class='SIMULATED_PASS'
 switch($case){'wrongTarget' {$e.aclCorroboration[1].role='control'} 'wrongFixture' {$e.aclFixtureBinding.fixtureId='ether-phase-a-store-'+('b'*32)} 'missingObservation' {$e.aclCorroboration=@($e.aclCorroboration[0],$e.aclCorroboration[2])} 'readFailed' {$e.aclCorroboration[1].status='UNVERIFIED'} 'contradictory' {$e.aclEstablishment[1].actual='D:P(A;;FA;;;SY)'} 'stale' {$e.aclCorroboration[1].sequence=0} 'missingRecord' {$e.aclEstablishment=@($e.aclEstablishment[0])} 'relabeled' {foreach($x in $e.aclEstablishment){$x.source='LIVE'};foreach($x in $e.aclCorroboration){$x.source='LIVE'};$e.aclFixtureBinding.source='LIVE';$class='LIVE_OBSERVED'}}
 $v2=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v2 $e $class $journal.ToArray();if($v2.cases.aclInspection.state -cne 'NOT_RUN'){throw "invalid inspection accepted: $case"}
}
foreach($case in @('inheritance','missingAce','extraAce')){
 $e=$ev.Clone();$e.cleanupVerified=$false;$e.aclEstablishment=@($records[0].Clone(),$records[1].Clone());$e.aclCorroboration=@($observations[0].Clone(),$observations[1].Clone());$r=$e.aclEstablishment[1];$o=$e.aclCorroboration[1]
 if($case -ceq 'inheritance'){$r.actual=$r.actual.Replace('D:P','D:');$r.actualProtected=$false;$o.protected=$false}elseif($case -ceq 'missingAce'){$r.actual='D:P(A;;FA;;;SY)'}else{$r.actual=$r.actual+'(A;OICI;FA;;;WD)'};$r.reason='DESCRIPTOR_MISMATCH';$o.descriptor=$r.actual
 $v2=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v2 $e 'SIMULATED_PASS' $journal.ToArray();if($v2.cases.aclInspection.state -cne 'FAIL'){throw "inspection violation lost: $case"};$check=New-PhaseAEvidenceVerifier $journal.ToArray() $v2 '1' $true $true 'SIMULATED_PASS' @() @{} $e;if(-not (& $check 'aclInspection' $v2.cases.aclInspection $v2)){throw 'inspection violation did not recheck'};if((Get-PhaseAVerdict $v2 $check).status -cne 'UNVERIFIED'){throw 'incomplete cleanup reached final verdict'}
}
$oldDescriptor=$observations[1].descriptor;$observations[1].descriptor='D:P(A;;FA;;;SY)';if(& $verify 'aclInspection' $v.cases.aclInspection $v){throw 'stale proof accepted after observation changed'};$observations[1].descriptor=$oldDescriptor
$rootFailure=$ev.Clone();$rootFailure.cleanupVerified=$false;$rootFailure.aclEstablishment=@($records[0].Clone());$rootFailure.aclCorroboration=@($observations[0].Clone());$rootFailure.aclEstablishment[0].actual='D:P(A;;FA;;;SY)';$rootFailure.aclEstablishment[0].reason='DESCRIPTOR_MISMATCH';$rootFailure.aclCorroboration[0].descriptor=$rootFailure.aclEstablishment[0].actual;$rv=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $rv $rootFailure 'SIMULATED_PASS' $journal.ToArray();if($rv.cases.aclInspection.state -cne 'NOT_RUN'){throw 'root violation attributed to protected inspection'}
$protectedFailure=$e
. "$PSScriptRoot/PhaseA.InventoryBridge.Tests.ps1"
$fakeState.created=$false;$fakeState.mutated=$false;$script:sequence=0;$script:cleanupEvents=New-Object 'System.Collections.Generic.List[string]';$fixtureId=[IO.Path]::GetFileName($fakeFixture.root);foreach($x in $protectedFailure.aclEstablishment){$x.fixtureId=$fixtureId};foreach($x in $protectedFailure.aclCorroboration){$x.fixtureId=$fixtureId};$protectedFailure.aclFixtureBinding=$protectedFailure.aclFixtureBinding.Clone();$protectedFailure.aclFixtureBinding.fixtureId=$fixtureId;$protectedFailure.aclFixtureBinding.rootIdentity=$fakeFixture.root
$failingFixture.Setup={param($accounts,$evidence,$observer) $evidence.aclEstablishment=$protectedFailure.aclEstablishment;$evidence.aclCorroboration=$protectedFailure.aclCorroboration;$evidence.aclFixtureBinding=$protectedFailure.aclFixtureBinding;return $fakeFixture}.GetNewClosure();$j=New-Object 'System.Collections.Generic.List[object]';$wrapped=New-PhaseAActorJournalBackend $failingActors $j;$out=@{};$status=Invoke-PhaseAStages $true $true $accountBackend $wrapped $true $failingFixture $out
if($status -cne 'ACCOUNT_CLEANUP_FAILED' -or $script:cleanupEvents.Count -ne 0 -or $out.evidence.cleanupVerified){throw 'unconfirmed child cleanup gate failed'}
$vv=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $vv $out.evidence 'SIMULATED_PASS' $j.ToArray();if($vv.cases.aclInspection.state -cne 'FAIL'){throw 'inspection violation lost after unconfirmed child'};$vc=New-PhaseAEvidenceVerifier $j.ToArray() $vv '1' $true $true 'SIMULATED_PASS' @() @{} $out.evidence;if(-not (& $vc 'aclInspection' $vv.cases.aclInspection $vv)){throw 'inspection violation did not recheck after unconfirmed child'}
Write-Output 'PASS ACL inspection positive and negative controls'
